// Revizyon karşılaştırmasının saf mantığı: durum sayıları, değişen alanlar ve Türkçe yazımlar. Değerler ABACUS ile yazılır
// (para kuruş tam sayısından, sayı "1.234,5", tarih "16.10.2026"). Eşleştirmeyi proje yapar; burada yalnız gösterim kararı var.
// Saf dosya: React yok, test edilir.
import { date as abacusDate, money } from "@snn/abacus-core";

export type RevisionStatus = "added" | "removed" | "changed" | "unmatched" | "same";
export type RevisionFieldFormat = "text" | "number" | "money" | "date";
/** Gösterilecek alan. `money` değeri kuruş tam sayısıdır. */
export type RevisionField = { key: string; label: string; format?: RevisionFieldFormat; currency?: "TRY" | "USD" | "EUR"; digits?: number };
/** Proje tarafından eşlenmiş satır. `before` önceki sürümdeki, `after` yeni sürümdeki değerlerdir; eklenen satırda yalnız `after`, silinende yalnız `before` olur. */
export type RevisionRow = { key: string; status: RevisionStatus; before?: Record<string, unknown>; after?: Record<string, unknown>; note?: string };
export type FieldChange = { field: RevisionField; before: string; after: string };

/** Süzgeç ve özetin sırası. */
export const STATUS_ORDER: RevisionStatus[] = ["added", "removed", "changed", "unmatched", "same"];
export const statusLabel: Record<RevisionStatus, string> = { added: "Eklendi", removed: "Silindi", changed: "Değişti", unmatched: "Eşlenmedi", same: "Aynı" };

const isEmpty = (value: unknown) => value == null || value === "";
const isoOf = (value: Date) => `${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, "0")}-${String(value.getDate()).padStart(2, "0")}`;
const decimalsOf = (value: number) => (String(value).split(".")[1] ?? "").length;

/** Alan değerini yazar: para "₺1.234,50", sayı "1.234,5", tarih "16.10.2026", boş "–". Biçim verilmezse türe bakılır. */
export function formatValue(value: unknown, field: RevisionField): string {
  if (isEmpty(value)) return "–";
  const format = field.format ?? (typeof value === "number" ? "number" : value instanceof Date ? "date" : "text");
  if (format === "money" && typeof value === "number") return money.format(value, { currency: field.currency ?? "TRY", kurus: true, zero: "symbol" });
  if (format === "number" && typeof value === "number") {
    const text = money.fmtDecimalGrouped(Math.abs(value), field.digits ?? Math.min(4, decimalsOf(value)));
    return value < 0 && text !== "—" ? `-${text}` : text;
  }
  if (format === "date") return abacusDate.format(value instanceof Date ? isoOf(value) : String(value), "short");
  return String(value);
}

/** Değişen alanlar: iki sürümde yazımı farklı olan alanlar. Yazımla karşılaştırmak 1250 ile 1250.0'ı aynı sayar. */
export function changedFields(row: RevisionRow, fields: readonly RevisionField[]): FieldChange[] {
  return fields.flatMap(field => {
    const before = formatValue(row.before?.[field.key], field), after = formatValue(row.after?.[field.key], field);
    return before === after ? [] : [{ field, before, after }];
  });
}

/** Satırın bir yanındaki dolu alanlar (eklenen, silinen ya da eşlenmeyen satır için). */
export function sideFields(values: Record<string, unknown> | undefined, fields: readonly RevisionField[]) {
  return fields.flatMap(field => (isEmpty(values?.[field.key]) ? [] : [{ field, value: formatValue(values?.[field.key], field) }]));
}

export function countByStatus(rows: readonly RevisionRow[]): Record<RevisionStatus, number> {
  const counts: Record<RevisionStatus, number> = { added: 0, removed: 0, changed: 0, unmatched: 0, same: 0 };
  for (const row of rows) counts[row.status] += 1;
  return counts;
}

/** Özet: "3 eklendi, 1 silindi, 4 değişti". Aynı kalanlar sayılmaz; fark yoksa "Fark yok". */
export function summaryText(counts: Record<RevisionStatus, number>) {
  const parts = STATUS_ORDER.filter(status => status !== "same" && counts[status] > 0).map(status => `${money.fmtDecimalGrouped(counts[status])} ${statusVerb[status]}`);
  return parts.length ? parts.join(", ") : "Fark yok";
}
const statusVerb: Record<RevisionStatus, string> = { added: "eklendi", removed: "silindi", changed: "değişti", unmatched: "eşlenmedi", same: "aynı" };

/** Satırın başlığı: birincil alanın yeni, yoksa önceki değeri; ikisi de yoksa anahtar. */
export function rowTitle(row: RevisionRow, primary: RevisionField) {
  const value = isEmpty(row.after?.[primary.key]) ? row.before?.[primary.key] : row.after?.[primary.key];
  return isEmpty(value) ? row.key : formatValue(value, primary);
}

/** Eşlenmeyen satırın hangi sürümde olduğu. */
export const unmatchedSide = (row: RevisionRow) => (row.after && !row.before ? "Yalnız yeni sürümde" : row.before && !row.after ? "Yalnız önceki sürümde" : "İki sürümde de eşi bulunamadı");

/* Renk kararı: eklendi yeşil, değişti vurgu, eşlenmedi uyarı tonu (SNN'de mavi-gri), silindi gri ve üstü çizili. Silmek hata
   değildir; kırmızı yalnız gerçek hata içindir (arayuz-standardi.md). Amber yok. */
.root { --tone: var(--text-muted); container: revision / inline-size; width: 100%; min-width: 0; overflow: hidden; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); color: var(--foreground); font-family: var(--font-body); letter-spacing: var(--tracking-body); }
.header { display: grid; gap: var(--space-2); padding: var(--space-4); border-bottom: 1px solid var(--border); }
.title { margin: 0; font-size: var(--text-base); font-weight: 500; line-height: var(--leading-body); }
.summary { margin: 0; color: var(--text-muted); font-size: var(--text-sm); line-height: var(--leading-body); }
.filters { display: flex; flex-wrap: wrap; gap: var(--space-1); margin-top: var(--space-1); }
/* Süzgeç düğmesi: sakin hap; seçili olan dolgulu. Sayı eş genişlikli rakamla. */
.filter { display: inline-flex; height: 30px; align-items: center; gap: 6px; border: 1px solid var(--border); border-radius: var(--radius-pill); padding: 0 var(--space-3); background: var(--surface); color: var(--text-secondary); font: inherit; font-size: var(--text-sm); cursor: pointer; -webkit-tap-highlight-color: transparent; transition: background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard), border-color var(--duration-fast) var(--ease-standard), scale var(--duration-spring) var(--ease-spring); }
.filter[aria-pressed="true"] { border-color: var(--foreground); background: var(--foreground); color: var(--background); }
.count { font-variant-numeric: tabular-nums; opacity: .7; }
@media (hover: hover) and (pointer: fine) { .filter:hover:not([aria-pressed="true"]) { border-color: var(--border-strong); background: var(--surface-muted); color: var(--foreground); } }
.filter:active { scale: .97; transition-duration: var(--duration-fast), var(--duration-fast), var(--duration-fast), 100ms; }

.list { display: grid; margin: 0; padding: 0; list-style: none; }
/* Satır: solda durum rozeti için sabit sütun, sağda başlık ve alanlar. Dar kapta rozet başlığın üstüne çıkar. */
.row { display: grid; grid-template-columns: 112px minmax(0, 1fr); align-items: start; gap: var(--space-3); padding: var(--space-3) var(--space-4); border-bottom: 1px solid var(--border-subtle); background: var(--surface); font-size: var(--text-sm); line-height: var(--leading-body); }
.row:last-child { border-bottom: 0; }
.row[data-status="added"] { --tone: var(--success); }
.row[data-status="changed"] { --tone: var(--accent-strong); }
.row[data-status="unmatched"] { --tone: var(--warning); }
.row[data-status="removed"], .row[data-status="same"] { --tone: var(--text-muted); }
.badge { display: inline-flex; width: fit-content; align-items: center; gap: 5px; border-radius: var(--radius-pill); padding: 2px 9px 2px 7px; background: color-mix(in oklab, var(--tone) 12%, var(--surface)); color: var(--tone); font-size: var(--text-xs); font-weight: 500; line-height: 20px; white-space: nowrap; }
.body { display: grid; min-width: 0; gap: 6px; }
.rowTitle { min-width: 0; font-weight: 500; overflow-wrap: anywhere; }
.row[data-status="removed"] .rowTitle { color: var(--text-secondary); text-decoration: line-through; text-decoration-color: color-mix(in oklab, var(--text-muted) 70%, transparent); }
/* Alanlar etiket–değer çiftleri; geniş kapta iki sütun, dar kapta tek sütun. */
.fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 4px var(--space-4); margin: 0; }
.field { display: flex; min-width: 0; align-items: baseline; justify-content: space-between; gap: var(--space-2); font-size: var(--text-xs); }
.field dt { flex: none; color: var(--text-muted); }
.field dd { min-width: 0; margin: 0; color: var(--text-secondary); font-variant-numeric: tabular-nums; text-align: right; overflow-wrap: anywhere; }
.change { display: inline-flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: 4px; }
.change del, .field del { color: var(--text-muted); text-decoration: line-through; text-decoration-color: color-mix(in oklab, var(--text-muted) 70%, transparent); }
.change ins { border-radius: 4px; padding: 0 4px; background: color-mix(in oklab, var(--accent) 12%, var(--surface)); color: var(--foreground); font-weight: 500; text-decoration: none; }
.arrow { flex: none; color: var(--text-muted); }
.rest { grid-column: 1 / -1; color: var(--text-muted); font-size: var(--text-xs); }
.note { margin: 0; color: var(--text-muted); font-size: var(--text-xs); }
.empty { padding: var(--space-6) var(--space-4); color: var(--text-muted); font-size: var(--text-sm); text-align: center; }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }

@container revision (max-width: 36rem) {
  .row { grid-template-columns: minmax(0, 1fr); gap: 6px; }
  .fields { grid-template-columns: minmax(0, 1fr); }
}
@media (prefers-reduced-motion: reduce) {
  .filter { transition: none; }
  .filter:active { scale: none; }
}

"use client";

import { useMemo, useState } from "react";
import { ArrowRight, CircleHelp, Equal, Minus, PenLine, Plus } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import { STATUS_ORDER, changedFields, countByStatus, rowTitle, sideFields, statusLabel, summaryText, unmatchedSide } from "./revision-diff-format";
import type { RevisionField, RevisionRow, RevisionStatus } from "./revision-diff-format";
import styles from "./revision-diff.module.css";

export type { RevisionField, RevisionRow, RevisionStatus };

export interface RevisionDiffProps {
  /** Proje tarafından eşlenmiş satırlar. Bileşen eşleştirme yapmaz, yalnız gösterir. */
  rows: RevisionRow[];
  /** Gösterilecek alanlar, sırasıyla. İlki (ya da `primaryKey`) satırın başlığıdır. */
  fields: RevisionField[];
  primaryKey?: string;
  title?: string;
  /** Değişen alanlarda eski ve yeni değerin ekran okuyucu adları. */
  beforeLabel?: string;
  afterLabel?: string;
  /** Aynı kalan satırlar varsayılan olarak gizlidir; süzgeçte "Aynı" seçilince ya da bu açıkken görünür. */
  showUnchanged?: boolean;
  emptyMessage?: string;
  className?: string;
}

type Filter = "all" | RevisionStatus;
const ICONS: Record<RevisionStatus, typeof Plus> = { added: Plus, removed: Minus, changed: PenLine, unmatched: CircleHelp, same: Equal };
const enter = { duration: motionTokens.duration.standard, ease: [...motionTokens.ease.enter] } as const;
const leave = { duration: motionTokens.duration.fast, ease: [...motionTokens.ease.standard] } as const;

/**
 * Revizyon karşılaştırması: iki sürüm arasındaki satır farkları. Üstte özet ve sayılı süzgeç düğmeleri (Tümü, Eklendi,
 * Silindi, Değişti, Eşlenmedi, Aynı); altta her satır durum rozeti, başlık ve alanlarıyla. Değişen satırda yalnız değişen
 * alanlar "eski → yeni" olarak yazılır, kalanların sayısı söylenir. Eklenen satır yeni, silinen satır üstü çizili eski
 * değerleri gösterir. Değerler ABACUS ile yazılır. Arc'ta karşılığı yok; SNN-UI için yazıldı.
 */
export function RevisionDiff({ rows, fields, primaryKey, title, beforeLabel = "Önceki", afterLabel = "Yeni", showUnchanged = false, emptyMessage = "Gösterilecek fark yok", className }: RevisionDiffProps) {
  const reduced = useReducedMotion() ?? false;
  const [filter, setFilter] = useState<Filter>("all");
  const counts = useMemo(() => countByStatus(rows), [rows]);
  const primary = fields.find(field => field.key === primaryKey) ?? fields[0];
  const others = fields.filter(field => field !== primary);
  const visible = rows.filter(row => (filter === "all" ? row.status !== "same" || showUnchanged : row.status === filter));
  const filters: Filter[] = ["all", ...STATUS_ORDER.filter(status => counts[status] > 0)];
  const visibleCount = (value: Filter) => (value === "all" ? rows.length - (showUnchanged ? 0 : counts.same) : counts[value]);

  return <section className={[styles.root, className].filter(Boolean).join(" ")} aria-label={title ?? "Revizyon karşılaştırması"}>
    <header className={styles.header}>
      {title ? <h3 className={styles.title}>{title}</h3> : null}
      <p className={styles.summary}>{summaryText(counts)}</p>
      <div className={styles.filters} role="group" aria-label="Duruma göre süz">
        {filters.map(value => <button key={value} type="button" className={styles.filter} data-status={value} aria-pressed={filter === value} onClick={() => setFilter(value)}>
          <span>{value === "all" ? "Tümü" : statusLabel[value]}</span><span className={styles.count}>{visibleCount(value)}</span>
        </button>)}
      </div>
    </header>
    <ul className={styles.list}>
      <AnimatePresence initial={false} mode="popLayout">
        {visible.length ? visible.map(row => {
          const Icon = ICONS[row.status];
          const changes = row.status === "changed" ? changedFields(row, others) : [];
          const unchanged = others.length - changes.length;
          const side = row.status === "removed" || (row.status === "unmatched" && !row.after) ? row.before : row.after;
          return <motion.li key={row.key} className={styles.row} data-status={row.status} layout={reduced ? false : "position"}
            initial={reduced ? { opacity: 0 } : { opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0, transition: reduced ? { duration: 0 } : enter }} exit={{ opacity: 0, transition: reduced ? { duration: 0 } : leave }}
            transition={motionTokens.spring.smooth}>
            <span className={styles.badge}><Icon size={14} strokeWidth={2} aria-hidden="true" />{statusLabel[row.status]}</span>
            <div className={styles.body}>
              <div className={styles.rowTitle}>{primary ? rowTitle(row, primary) : row.key}</div>
              {row.status === "changed" ? <dl className={styles.fields}>
                {changes.map(change => <div key={change.field.key} className={styles.field}>
                  <dt>{change.field.label}</dt>
                  <dd className={styles.change}>
                    <del><span className={styles.srOnly}>{beforeLabel}: </span>{change.before}</del>
                    <ArrowRight className={styles.arrow} size={14} strokeWidth={1.75} aria-hidden="true" />
                    <ins><span className={styles.srOnly}>{afterLabel}: </span>{change.after}</ins>
                  </dd>
                </div>)}
                {unchanged > 0 && row.status === "changed" ? <div className={styles.rest}>{unchanged} alan aynı</div> : null}
              </dl> : <dl className={styles.fields}>
                {sideFields(side, others).map(item => <div key={item.field.key} className={styles.field}>
                  <dt>{item.field.label}</dt>
                  <dd>{row.status === "removed" ? <del>{item.value}</del> : item.value}</dd>
                </div>)}
              </dl>}
              {row.status === "unmatched" || row.note ? <p className={styles.note}>{[row.status === "unmatched" ? unmatchedSide(row) : "", row.note ?? ""].filter(Boolean).join(". ")}</p> : null}
            </div>
          </motion.li>;
        }) : <motion.li key="empty" className={styles.empty} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>{emptyMessage}</motion.li>}
      </AnimatePresence>
    </ul>
  </section>;
}

export default RevisionDiff;
